<script setup lang="ts">import {probability} from '../utils/format';defineProps<{rows:any[],nodes:any[]}>()</script><template><div class="table-wrap"><table><thead><tr><th>节点</th><th>父顺序</th><th>父配置</th><th>P(0)</th><th>P(1)</th><th>行和</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r.node_id}}</td><td>{{nodes.find(n=>n.node_id===r.node_id)?.parents.join(', ')||'∅'}}</td><td>{{r.parent_values.join(', ')||'∅'}}</td><td>{{probability(r.p0)}}</td><td>{{probability(r.p1)}}</td><td>{{r.row_sum}}</td></tr></tbody></table></div></template>
